import React from 'react';
import ReactDOM from 'react-dom';
import { Table } from '@alifd/next';

const dataSource = [
  { id: 1, region: '有差异', before: {}, after: '无变化' },
  { id: 2, region: '未设置', before: '未设置', after: '无变化' },
  { id: 3, region: '空字符串', before: '', after: '无变化' },
  { id: 4, region: '上次选择', before: '未设置', after: '无变化' },
  { id: 5, region: '迪拜', before: '未设置 / 空字符串', after: '无变化' }
];

class App extends React.Component {
  render() {
    return (
      <Table
        dataSource={dataSource}
        primaryKey="id"
        rowSelection={{}}  // 开启选择模式，表头会自动插入一个“全选”列
      >
        {/* 用一个 ColumnGroup 包一层多级表头 */}
        <Table.ColumnGroup title="">
          <Table.Column
            title="区域"
            dataIndex="region"
          />
          <Table.Column
            title="设置前（当前值）"
            dataIndex="before"
            cell={value => <span style={{ color: 'red' }}>{JSON.stringify(value)}</span>}
          />
          <Table.Column
            title="设置后"
            dataIndex="after"
            cell={() => <span style={{ color: '#999' }}>无变化</span>}
          />
        </Table.ColumnGroup>
      </Table>
    );
  }
}

ReactDOM.render(<App />, document.getElementById('mountNode'));
